if(($argv[1]??'')==='worker'){$p=$argv[2]??'';if(!preg_match('/^essential_[a-f0-9]{10}_$/D',$p))exit(2);$input=json_decode(stream_get_contents(STDIN),true,64,JSON_THROW_ON_ERROR);$db=mutationRaceDb($p);$GLOBALS['essentialPrefix']=$p;$sales=new CompanySales($db,$p);try{switch($input['op']){case'edit':echo$sales->edit($input['issuer'],7,$input['id'],$input['payload'],$input['review'],$input['key']);break;case'copy':echo$sales->copy($input['issuer'],7,$input['id'],$input['payload'],$input['review'],$input['key']);break;case'decide':$sales->decide($input['issuer'],7,$input['id'],'accepted',$input['revision']);echo'accepted';break;case'convert':echo$sales->convert($input['issuer'],7,$input['id'],$input['revision']);break;default:throw new LogicException('unexpected operation');}}catch(DomainException$e){echo$e->getMessage();}exit(0);}
require __DIR__.'/sales_mutations.php';$observer=mutationRaceDb($p);$blocker=(int)$db->query('SELECT CONNECTION_ID() id')->row()->id;
function mutationRace(array$inputs,?callable$beforeRelease=null):array{global$db,$p,$observer,$blocker;$db->trans_begin();$db->query('SELECT id FROM '.$p.'issuers_lock WHERE id=1 FOR UPDATE');$workers=[];try{foreach($inputs as$input){$pipes=[];$process=proc_open([PHP_BINARY,__FILE__,'worker',$p],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new RuntimeException('worker unavailable');fwrite($pipes[0],json_encode($input,JSON_THROW_ON_ERROR));fclose($pipes[0]);$workers[]=[$process,$pipes];}$deadline=microtime(true)+15;do{$waiters=essentialLockWaiters($observer,$blocker);if($waiters>=2)break;usleep(20000);}while(microtime(true)<$deadline);essentialCheck($waiters>=2,'two real sales mutation connections observed waiting on installation lock');if($beforeRelease)$beforeRelease();$db->trans_commit();$out=[];foreach($workers as[$process,$pipes]){$value=stream_get_contents($pipes[1]);$error=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);essentialCheck(proc_close($process)===0&&$error==='','native mutation worker exits without diagnostics');$out[]=$value;}return$out;}finally{if($db->pdo->inTransaction())$db->trans_rollback();}}
