$id=$create('conversion');$r=$sales->document($b,7,$id);$sales->decide($b,7,$id,'accepted',$r['revision_token']);$r=$sales->document($b,7,$id);$before=(int)$db->query('SELECT COUNT(*) n FROM '.$p.'invoices')->row()->n;$task=['op'=>'convert','issuer'=>$b,'id'=>$id,'revision'=>$r['revision_token']];$out=mutationRace([$task,$task]);essentialCheck(ctype_digit($out[0])&&$out[0]===$out[1]&&(int)$db->query('SELECT COUNT(*) n FROM '.$p.'invoices')->row()->n===$before+1,'new review protocol retains one canonical invoice under simultaneous conversion');
